import React, { useState, useEffect } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import "./MainHeader.css";
import ContactForm from "../components/ContactForm";
import { useMapContext } from "./MapContext";
import { useUser } from "../contexts/UserContext";
import { doc, getDoc } from "firebase/firestore";
import { db } from "../firebase/firebaseConfig";
import { getFunctions, httpsCallable } from "firebase/functions";
import HighlightSettingsPopup from "../components/HighlightSettingsPopup";

const MainHeader = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [isContactFormOpen, setIsContactFormOpen] = useState(false);
  const { activeTab, setActiveTab } = useMapContext();
  const { user, logout } = useUser();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [subscriptionStatus, setSubscriptionStatus] = useState(null);
  const [role, setRole] = useState(null);
  const [showHighlightPopup, setShowHighlightPopup] = useState(false);
  const [showPortalRedirectPopup, setShowPortalRedirectPopup] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  // Check if we're on a product page (map, search, report, print)
  const isProductPage = ['/map', '/search', '/report', '/print'].includes(location.pathname);
  
  // Check if we're on the intro/landing page
  const isIntroPage = location.pathname === '/';

  // Listen for screen resize to update mobile state
  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth <= 768);
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const handleTabChange = (tab) => {
    setActiveTab(tab);
  };

  const handleContactClick = () => {
    setIsContactFormOpen(true);
  };

  const handleCloseContactForm = () => {
    setIsContactFormOpen(false);
  };

  const toggleDropdown = () => {
    setIsDropdownOpen((prev) => !prev);
  };

  const handleLogout = async () => {
    try {
      await logout();
      setIsDropdownOpen(false);
    } catch (error) {
      console.error("Error during logout:", error.message);
    }
  };

  // Fetch subscription info when user changes
  useEffect(() => {
    const fetchSubscriptionInfo = async () => {
      if (user) {
        const userDocRef = doc(db, "users", user.uid);
        const userSnap = await getDoc(userDocRef);
        if (userSnap.exists()) {
          const data = userSnap.data();
          setSubscriptionStatus(data.subscriptionStatus || "none");
          setRole(data.role || "none");
        } else {
          setSubscriptionStatus("none");
        }
      } else {
        setSubscriptionStatus(null);
      }
    };

    fetchSubscriptionInfo();
  }, [user]);

  const handleManageSubscription = async () => {
    try {
      setShowPortalRedirectPopup(true);
      const functions = getFunctions();
      const createPortalSession = httpsCallable(functions, "createPortalSession");
      const result = await createPortalSession({});
      const { url } = result.data;
      window.location.href = url;
    } catch (error) {
      console.error("Failed to create portal session:", error);
      alert("Unable to open portal. Please try again later.");
    }
  };

  return (
    <>
      {isIntroPage && (
        <div className="main-header intro-header">
          {/* Left - Logo (hidden on mobile) */}
          {!isMobile && (
            <div className="header-left">
              <Link to="/" className="logo-link">
                <img src="/logo.png" alt="Community View Logo" className="logo-image" />
              </Link>
            </div>
          )}

          {/* Center - Navigation Links */}
          <div className="header-center">
            <button className="nav-button" onClick={() => navigate('/tutorial')}>
              Tutorial
            </button>
            <a className="nav-button" href="mailto:noahgans@tetoncountygis.com">
              Contact
            </a>
          </div>

          {/* Right - Map + Account */}
          <div className="header-right">
            <button className="map-button" onClick={() => navigate('/map')}>
              Map
            </button>
            
            <div className="user-dropdown" onMouseEnter={() => setIsDropdownOpen(true)} onMouseLeave={() => setIsDropdownOpen(false)}>
              <button className="user-button" onClick={toggleDropdown}>
                {user ? "Account" : "Sign In"}
              </button>
              
              {/* Dropdown Menu */}
              {isDropdownOpen && (
                <div 
                  className="dropdown-menu"
                  onMouseEnter={() => setIsDropdownOpen(true)}
                  onMouseLeave={() => setIsDropdownOpen(false)}
                >
                  {user ? (
                    <>
                      <div className="dropdown-item">{user.email}</div>
                      <div
                        className={`subscription-status ${subscriptionStatus === 'active' ? 'active' : 'inactive'}`}
                      >
                        {subscriptionStatus === 'active' ? '✅ Subscribed' : '❌ Not Subscribed'}
                      </div>
                      {subscriptionStatus === "active" && (
                        <button className="dropdown-button" onClick={handleManageSubscription}>
                          Manage Subscription
                        </button>
                      )}
                      {(subscriptionStatus === "none" || subscriptionStatus === "canceled") && (
                        <button className="dropdown-button resubscribe-button" onClick={async () => {
                          try {
                            const functions = getFunctions();
                            const createCheckoutSession = httpsCallable(functions, "createCheckoutSession");
                            const result = await createCheckoutSession({
                              email: user.email,
                              userId: user.uid,
                            });
                            window.location.href = result.data.url;
                          } catch (err) {
                            console.error("Error re-subscribing:", err);
                            alert("Unable to start subscription. Please try again later.");
                          }
                        }}>
                          Subscribe
                        </button>
                      )}
                      <button className="dropdown-button logout-button" onClick={handleLogout}>
                        Sign Out
                      </button>
                      <button
                        className="dropdown-button"
                        onClick={() => setShowHighlightPopup(true)}
                      >
                        Highlight Settings
                      </button>
                    </>
                  ) : (
                    <button className="dropdown-button" onClick={() => window.location.href = "/login"}>
                      Sign In / Sign Up
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Main Header for product pages */}
      {!isIntroPage && (
        <div className="main-header">
          {/* Left Side - Logo/Home */}
          <div className="header-left">
            <Link to="/" className="logo-link">
              {isMobile ? (
                <span className="home-text">Home</span>
              ) : (
                <img src="/logo.png" alt="Community View Logo" className="logo-image" />
              )}
            </Link>
          </div>

          {/* Center - Navigation Tabs (only on product pages) */}
          {isProductPage && (
            <div className="header-center">
              <Link
                className={`header-tab ${activeTab === "map" ? "active" : ""}`}
                onClick={() => handleTabChange("map")}
                to="/map"
              >
                Map
              </Link>
              <Link
                className={`header-tab ${activeTab === "search" ? "active" : ""}`}
                onClick={() => handleTabChange("search")}
                to="/search"
              >
                Search
              </Link>
              {!isMobile && (
                <Link
                  className={`header-tab ${activeTab === "report" ? "active" : ""}`}
                  onClick={() => handleTabChange("report")}
                  to="/report"
                >
                  Reports
                </Link>
              )}
              {!isMobile && (
                <Link
                  className={`header-tab ${activeTab === "print" ? "active" : ""}`}
                  onClick={() => handleTabChange("print")}
                  to="/print"
                >
                  Print
                </Link>
              )}
            </div>
          )}

          {/* Right Side - Account (always visible) */}
          <div className="header-right">
            <div className="user-dropdown">
              <button
                className="user-button"
                onClick={toggleDropdown}
                onMouseEnter={() => setIsDropdownOpen(true)}
                onMouseLeave={() => {
                  setTimeout(() => {
                    if (!document.querySelector('.dropdown-menu:hover')) {
                      setIsDropdownOpen(false);
                    }
                  }, 100);
                }}
              >
                {user ? "Account" : "Sign In"}
              </button>

              {/* Dropdown Menu */}
              {isDropdownOpen && (
                <div 
                  className="dropdown-menu"
                  onMouseEnter={() => setIsDropdownOpen(true)}
                  onMouseLeave={() => setIsDropdownOpen(false)}
                >
                  {user ? (
                    <>
                      <div className="dropdown-item">{user.email}</div>
                      <div
                        className={`subscription-status ${subscriptionStatus === 'active' ? 'active' : 'inactive'}`}
                      >
                        {subscriptionStatus === 'active' ? '✅ Subscribed' : '❌ Not Subscribed'}
                      </div>
                      {subscriptionStatus === "active" && (
                        <button className="dropdown-button" onClick={handleManageSubscription}>
                          Manage Subscription
                        </button>
                      )}
                      {(subscriptionStatus === "none" || subscriptionStatus === "canceled") && (
                        <button className="dropdown-button resubscribe-button" onClick={async () => {
                          try {
                            const functions = getFunctions();
                            const createCheckoutSession = httpsCallable(functions, "createCheckoutSession");
                            const result = await createCheckoutSession({
                              email: user.email,
                              userId: user.uid,
                            });
                            window.location.href = result.data.url;
                          } catch (err) {
                            console.error("Error re-subscribing:", err);
                            alert("Unable to start subscription. Please try again later.");
                          }
                        }}>
                          Subscribe
                        </button>
                      )}
                      <button className="dropdown-button logout-button" onClick={handleLogout}>
                        Sign Out
                      </button>
                      <button
                        className="dropdown-button"
                        onClick={() => setShowHighlightPopup(true)}
                      >
                        Highlight Settings
                      </button>
                    </>
                  ) : (
                    <button className="dropdown-button" onClick={() => window.location.href = "/login"}>
                      Sign In / Sign Up
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Modals */}
      {isContactFormOpen && <ContactForm onClose={handleCloseContactForm} />}
      {showHighlightPopup && (
        <HighlightSettingsPopup onClose={() => setShowHighlightPopup(false)} />
      )}
      {showPortalRedirectPopup && (
        <div className="popup-overlay">
          <div className="popup">
            <p> Taking you to your secure billing portal... Please wait.</p>
          </div>
        </div>
      )}
    </>
  );
};

export default MainHeader;
